#include "tracking/camera_visibility_graph.h"
namespace nox::native::tracking{void CameraVisibilityGraph::update(std::uint32_t c,std::uint64_t s,bool v){if(v)visible_[c].insert(s);else if(auto it=visible_.find(c);it!=visible_.end())it->second.erase(s);}bool CameraVisibilityGraph::visible(std::uint32_t c,std::uint64_t s)const noexcept{auto it=visible_.find(c);return it!=visible_.end()&&it->second.contains(s);}double CameraVisibilityGraph::coverage(std::uint64_t s)const noexcept{if(visible_.empty())return 0;std::size_t n=0;for(auto&[_,set]:visible_)n+=set.contains(s)?1:0;return static_cast<double>(n)/visible_.size();}}